insert into change_headers (id, ts) values (68, '2026-10-19') on duplicate key update ts = values(ts);
insert into change_descriptions (id, lang, description) values (68, 'ru', 'Во всех калькуляторах появились профили игрока. Профиль хранит данные аккаунта OGame — планеты и луны, исследования, офицеров, классы, бонусы форм жизни — и заполняется импортом из скрипта Origin Exporter или вручную. Калькуляторы берут из него нужные значения и уровни выбранной планеты; изменённое поле помечается и одним щелчком возвращается к игровому значению. Профили хранятся в браузере, их можно сохранить в файл и восстановить.<br>Терраформер: добавлено снижение стоимости от Терраформера форм жизни. Луны: доля обороны в обломках задаётся отдельно. Гравитон и Терраформер: бонус офицеров — флажок на каждого. Стоимость: у сети исследований свой флажок.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (68, 'en', 'Player profiles have arrived in every calculator. A profile holds the data of an OGame account — planets and moons, research, officers, classes, life form bonuses — and is filled by importing from the Origin Exporter script or by hand. The calculators take the values they need from it, along with the levels of the selected planet; a changed field is marked and goes back to the game value with one click. Profiles are stored in your browser and can be saved to a file and restored.<br>Terraformer: added the cost reduction from the life form Terraformer. Moon: the share of defenses going to the debris field is set separately. Graviton and Terraformer: the officers'' bonus is now a checkbox per officer. Costs: the research network has a checkbox of its own.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (68, 'pt', 'Todas as calculadoras passaram a ter perfis de jogador. Um perfil guarda os dados de uma conta do OGame — planetas e luas, pesquisas, oficiais, classes, bónus das formas de vida — e é preenchido por importação a partir do script Origin Exporter ou manualmente. As calculadoras tiram dele os valores necessários e os níveis do planeta escolhido; um campo alterado fica marcado e volta ao valor do jogo com um clique. Os perfis ficam guardados no navegador e podem ser gravados num ficheiro e restaurados.<br>Terraformador: adicionada a redução de custo do Terraformador das formas de vida. Lua: a parte das defesas que vai para o campo de destroços é definida à parte. Graviton e Terraformador: o bónus dos oficiais passa a ser uma caixa por oficial. Custos: a rede de pesquisa tem a sua própria caixa.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (68, 'de', 'Alle Rechner haben jetzt Spielerprofile. Ein Profil speichert die Daten eines OGame-Accounts — Planeten und Monde, Forschungen, Offiziere, Klassen, Lebensform-Boni — und wird per Import aus dem Skript Origin Exporter oder von Hand befüllt. Die Rechner übernehmen daraus die benötigten Werte und die Stufen des gewählten Planeten; ein geändertes Feld wird markiert und lässt sich mit einem Klick auf den Spielwert zurücksetzen. Profile werden im Browser gespeichert und lassen sich in eine Datei sichern und wiederherstellen.<br>Terraformer: die Kostensenkung durch den Lebensform-Terraformer wurde ergänzt. Mond: der Anteil der Verteidigung im Trümmerfeld wird separat eingestellt. Graviton und Terraformer: der Offiziersbonus ist jetzt ein Kästchen pro Offizier. Kosten: das Forschungsnetzwerk hat ein eigenes Kästchen.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (68, 'pl', 'Wszystkie kalkulatory mają teraz profile gracza. Profil przechowuje dane konta OGame — planety i księżyce, badania, oficerów, klasy, bonusy form życia — i jest wypełniany importem ze skryptu Origin Exporter lub ręcznie. Kalkulatory pobierają z niego potrzebne wartości oraz poziomy wybranej planety; zmienione pole jest oznaczane i jednym kliknięciem wraca do wartości z gry. Profile są przechowywane w przeglądarce, można je zapisać do pliku i przywrócić.<br>Terraformer: dodano obniżkę kosztów z Terraformera form życia. Księżyc: udział obrony w polu zniszczeń ustawia się osobno. Grawiton i Terraformer: bonus oficerów to teraz pole wyboru dla każdego oficera. Koszty: sieć badań ma własne pole wyboru.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (68, 'es', 'Todas las calculadoras tienen ahora perfiles de jugador. Un perfil guarda los datos de una cuenta de OGame — planetas y lunas, investigaciones, oficiales, clases, bonificaciones de las formas de vida — y se rellena importando desde el script Origin Exporter o a mano. Las calculadoras toman de él los valores necesarios y los niveles del planeta elegido; un campo modificado queda marcado y vuelve al valor del juego con un clic. Los perfiles se guardan en el navegador y pueden guardarse en un archivo y restaurarse.<br>Terraformer: añadida la reducción de coste del Terraformer de las formas de vida. Luna: la parte de las defensas que va al campo de escombros se ajusta por separado. Gravitón y Terraformer: la bonificación de oficiales es ahora una casilla por oficial. Costes: la red de investigación tiene su propia casilla.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (68, 'fr', 'Tous les calculateurs ont désormais des profils de joueur. Un profil conserve les données d''un compte OGame — planètes et lunes, recherches, officiers, classes, bonus des formes de vie — et se remplit par import depuis le script Origin Exporter ou à la main. Les calculateurs y prennent les valeurs utiles et les niveaux de la planète choisie ; un champ modifié est signalé et revient à la valeur du jeu d''un clic. Les profils sont stockés dans le navigateur et peuvent être sauvegardés dans un fichier puis restaurés.<br>Terraformeur : ajout de la réduction de coût du Terraformeur des formes de vie. Lune : la part des défenses envoyée dans le champ de débris se règle à part. Graviton et Terraformeur : le bonus des officiers est une case par officier. Coûts : le réseau de recherche a sa propre case.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (68, 'it', 'Tutti i calcolatori ora hanno i profili giocatore. Un profilo conserva i dati di un account OGame — pianeti e lune, ricerche, ufficiali, classi, bonus delle forme di vita — e si compila importando dallo script Origin Exporter o a mano. I calcolatori ne prendono i valori necessari e i livelli del pianeta scelto; un campo modificato viene segnalato e torna al valore di gioco con un clic. I profili sono salvati nel browser e si possono esportare in un file e ripristinare.<br>Terraformer: aggiunta la riduzione dei costi del Terraformer delle forme di vita. Luna: la quota delle difese che finisce nel campo detriti si imposta a parte. Gravitone e Terraformer: il bonus ufficiali è ora una casella per ufficiale. Costi: la rete di ricerca ha una casella propria.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (68, 'nl', 'Alle calculators hebben nu spelersprofielen. Een profiel bewaart de gegevens van een OGame-account — planeten en manen, onderzoeken, officieren, klassen, levensvormbonussen — en wordt gevuld door te importeren uit het script Origin Exporter of met de hand. De calculators halen er de benodigde waarden en de niveaus van de gekozen planeet uit; een gewijzigd veld wordt gemarkeerd en gaat met één klik terug naar de spelwaarde. Profielen worden in de browser opgeslagen en kunnen naar een bestand worden bewaard en hersteld.<br>Terraformer: de kostenverlaging van de levensvorm-Terraformer is toegevoegd. Maan: het deel van de verdediging dat in het puinveld belandt, wordt apart ingesteld. Graviton en Terraformer: de officiersbonus is nu een vakje per officier. Kosten: het onderzoeksnetwerk heeft een eigen vakje.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (68, 'sk', 'Všetky kalkulačky majú teraz profily hráča. Profil uchováva údaje účtu OGame — planéty a mesiace, výskumy, dôstojníkov, triedy, bonusy foriem života — a vypĺňa sa importom zo skriptu Origin Exporter alebo ručne. Kalkulačky z neho berú potrebné hodnoty a úrovne zvolenej planéty; zmenené pole sa označí a jedným kliknutím sa vráti na hodnotu z hry. Profily sa ukladajú v prehliadači, dajú sa uložiť do súboru a obnoviť.<br>Terraformer: pridané zníženie ceny od Terraformera foriem života. Mesiac: podiel obrany v poli trosiek sa nastavuje samostatne. Graviton a Terraformer: bonus dôstojníkov je teraz zaškrtávacie pole pre každého dôstojníka. Náklady: sieť výskumu má vlastné zaškrtávacie pole.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (68, 'tr', 'Tüm hesaplayıcılarda artık oyuncu profilleri var. Profil bir OGame hesabının verilerini — gezegenler ve aylar, araştırmalar, subaylar, sınıflar, yaşam formu bonusları — saklar ve Origin Exporter betiğinden içe aktarılarak ya da elle doldurulur. Hesaplayıcılar gereken değerleri ve seçilen gezegenin seviyelerini buradan alır; değiştirilen alan işaretlenir ve tek tıkla oyundaki değere döner. Profiller tarayıcıda saklanır, bir dosyaya kaydedilip geri yüklenebilir.<br>Terraformer: yaşam formu Terraformer''ının maliyet indirimi eklendi. Ay: savunmaların enkaz alanına giden payı ayrı ayarlanır. Graviton ve Terraformer: subay bonusu artık her subay için bir onay kutusu. Maliyetler: araştırma ağının kendi onay kutusu var.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (68, 'bs', 'Svi kalkulatori sada imaju profile igrača. Profil čuva podatke OGame računa — planete i mjesece, istraživanja, oficire, klase, bonuse oblika života — i popunjava se uvozom iz skripte Origin Exporter ili ručno. Kalkulatori iz njega uzimaju potrebne vrijednosti i nivoe odabrane planete; promijenjeno polje se označi i jednim klikom vraća na vrijednost iz igre. Profili se čuvaju u pregledniku i mogu se sačuvati u datoteku i vratiti.<br>Terraformer: dodano smanjenje cijene od Terraformera oblika života. Mjesec: udio odbrane u polju ruševina podešava se zasebno. Graviton i Terraformer: bonus oficira je sada kvadratić za svakog oficira. Troškovi: mreža istraživanja ima svoj kvadratić.') on duplicate key update description = values(description);
